namespace sv_a9a9d19fc79e4ec1953dee0ba8b0915d.Client.Models;

public record Shipment(
    string TrackingNumber,
    string Status,
    string Location,
    DateTimeOffset EstimatedDelivery,
    IReadOnlyList<StatusUpdate> StatusUpdates);

public record StatusUpdate(
    string Description,
    string Location,
    DateTimeOffset Timestamp);

using sv_a9a9d19fc79e4ec1953dee0ba8b0915d.Client.Models;

namespace sv_a9a9d19fc79e4ec1953dee0ba8b0915d.Client.Services;

public interface IShipmentService
{
    Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct);
}

using System.Net.Http.Json;
using sv_a9a9d19fc79e4ec1953dee0ba8b0915d.Client.Models;

namespace sv_a9a9d19fc79e4ec1953dee0ba8b0915d.Client.Services;

/// <summary>
/// HTTP-based implementation used when running on WebAssembly.
/// Calls the server API endpoint to retrieve shipment data.
/// </summary>
public class ShipmentClientService : IShipmentService
{
    private readonly HttpClient _http;

    public ShipmentClientService(HttpClient http)
    {
        _http = http;
    }

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        var shipment = await _http.GetFromJsonAsync<Shipment>(
            $"api/shipments/{Uri.EscapeDataString(trackingNumber)}", ct);

        return shipment ?? throw new InvalidOperationException("Shipment not found.");
    }
}

using sv_a9a9d19fc79e4ec1953dee0ba8b0915d.Client.Models;
using sv_a9a9d19fc79e4ec1953dee0ba8b0915d.Client.Services;

namespace sv_a9a9d19fc79e4ec1953dee0ba8b0915d.Services;

/// <summary>
/// Server-side implementation that simulates a slow backend with fake data.
/// </summary>
public class ShipmentService : IShipmentService
{
    private static readonly Dictionary<string, Shipment> SeedData = new(StringComparer.OrdinalIgnoreCase)
    {
        ["TRK-001"] = new Shipment(
            TrackingNumber: "TRK-001",
            Status: "In Transit",
            Location: "Memphis, TN",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 11, 17, 0, 0, TimeSpan.FromHours(-5)),
            StatusUpdates: new List<StatusUpdate>
            {
                new("Package picked up", "New York, NY", new DateTimeOffset(2026, 7, 5, 9, 30, 0, TimeSpan.FromHours(-5))),
                new("Arrived at sorting facility", "Newark, NJ", new DateTimeOffset(2026, 7, 5, 14, 15, 0, TimeSpan.FromHours(-5))),
                new("Departed facility", "Newark, NJ", new DateTimeOffset(2026, 7, 6, 3, 0, 0, TimeSpan.FromHours(-5))),
                new("In transit", "Memphis, TN", new DateTimeOffset(2026, 7, 7, 8, 45, 0, TimeSpan.FromHours(-5)))
            }),

        ["TRK-002"] = new Shipment(
            TrackingNumber: "TRK-002",
            Status: "Delivered",
            Location: "Austin, TX",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 7, 12, 0, 0, TimeSpan.FromHours(-6)),
            StatusUpdates: new List<StatusUpdate>
            {
                new("Package picked up", "Seattle, WA", new DateTimeOffset(2026, 7, 3, 10, 0, 0, TimeSpan.FromHours(-8))),
                new("Arrived at sorting facility", "Portland, OR", new DateTimeOffset(2026, 7, 3, 18, 0, 0, TimeSpan.FromHours(-8))),
                new("In transit", "Dallas, TX", new DateTimeOffset(2026, 7, 5, 6, 0, 0, TimeSpan.FromHours(-6))),
                new("Out for delivery", "Austin, TX", new DateTimeOffset(2026, 7, 7, 8, 0, 0, TimeSpan.FromHours(-6))),
                new("Delivered", "Austin, TX", new DateTimeOffset(2026, 7, 7, 11, 32, 0, TimeSpan.FromHours(-6)))
            }),

        ["TRK-003"] = new Shipment(
            TrackingNumber: "TRK-003",
            Status: "Processing",
            Location: "Chicago, IL",
            EstimatedDelivery: new DateTimeOffset(2026, 7, 14, 17, 0, 0, TimeSpan.FromHours(-6)),
            StatusUpdates: new List<StatusUpdate>
            {
                new("Label created", "Chicago, IL", new DateTimeOffset(2026, 7, 7, 16, 0, 0, TimeSpan.FromHours(-6)))
            })
    };

    public async Task<Shipment> GetShipmentAsync(string trackingNumber, CancellationToken ct)
    {
        // Simulate slow backend
        await Task.Delay(1500, ct);

        if (SeedData.TryGetValue(trackingNumber, out var shipment))
        {
            return shipment;
        }

        throw new KeyNotFoundException($"No shipment found for tracking number '{trackingNumber}'.");
    }
}

